// Import createSlice and nanoid from Redux Toolkit
import { createSlice , nanoid } from '@reduxjs/toolkit' ;
// Define the initial state for the todos
const initialState = {
    todos: [{ id: 1, text: "Hello world"  }],
};
// Create a slice for the todo feature
export const todoSlice = createSlice ({
    name: 'todo', // Name of the slice
    initialState , // Initial state of the slice
    reducers : {
        // Reducer to add a new todo
        addTodo: (state, action) => {
            const todo = {
                id: nanoid(), // Generate a unique id using nanoid
                text: action.payload, // Use the text passed in the action payload
            };
            state.todos.push(todo); // Add the new todo to the state
        },
        // Reducer to remove a todo by id
        removeTodo : (state, action) => {
            state.todos = state.todos.filter((todo) => todo.id !== action.payload);
            // Update the state by filtering out the todo with the matching id
        },
    },
});
// Export actions to use them in components
export const { addTodo , removeTodo } = todoSlice .actions;

Reducers :
addTodo Takes the cur rent state and an action as ar guments. It adds a ne w todo item to the todos array. The ne w 
todo item is created with a unique id using nanoid and the t ext passed in action.payload.
removeTodo Takes the cur rent state and an action. I t filters the todos array to remove the todo item with the id 
provided in action.payload.
Action Cr eators: addTodo and removeTodo action cr eators are automatically generat ed and e xported from the slice.
